                    delta, j, ins, new_ri, new_rj = best
                    routes[i] = new_ri
                    routes[j] = new_rj
                    loads[i] -= demands[cust]
                    loads[j] += demands[cust]
                    costs[i] = route_cost(new_ri)
                    costs[j] = route_cost(new_rj)
                    if not routes[i]:
                        routes.pop(i)
                    improved_any = True
                    break
                if improved_any:
                    break
            if not improved_any:
                break

    relocate_phase()

    # 4) Inter-route 1-1 exchange (swap customers) if feasible and improves cost
    def exchange_phase():
        nonlocal routes
        for _ in range(4):
            improved_any = False
            m = len(routes)
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]

            i = 0
            while i < len(routes) and not improved_any:
                j = i + 1
                while j < len(routes) and not improved_any:
                    ri, rj = routes[i], routes[j]
                    if ri and rj:
                        base = costs[i] + costs[j]
                        # deterministic scan over positions
                        for pi in range(len(ri)):
                            a = ri[pi]
                            for pj in range(len(rj)):
                                b = rj[pj]
                                # feasibility check after swap
                                if loads[i] - demands[a] + demands[b] > capacity:
                                    continue
                                if loads[j] - demands[b] + demands[a] > capacity:
                                    continue
                                if a == b:
                                    continue
                                new_ri = ri[:pi] + [b] + ri[pi + 1:]
                                new_rj = rj[:pj] + [a] + rj[pj + 1:]
                                new_cost = route_cost(new_ri) + route_cost(new_rj)
                                if new_cost + 1e-9 < base:
                                    routes[i] = new_ri
                                    routes[j] = new_rj
                                    loads[i] = loads[i] - demands[a] + demands[b]
                                    loads[j] = loads[j] - demands[b] + demands[a]
                                    costs[i] = route_cost(new_ri)
                                    costs[j] = route_cost(new_rj)
                                    improved_any = True
                                    break
                            if improved_any:
                                break
                    j += 1
                i += 1
            if not improved_any:
                break

    exchange_phase()

    # 5) Final deterministic cleanup: remove empties (shouldn't happen except relocate)
    routes = [r for r in routes if r]
    return routes
